_SHIELD_VIEWBOX = "42.208853 97.816138 49.180267 56.232475"


def make_shield_svg(color: str = "#546ac1", size: int = 96) -> str:
    """Return a complete SVG string of the BulwarkOS shield at the given colour and size."""
    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" '
        f'viewBox="{_SHIELD_VIEWBOX}" width="{size}" height="{size}">'
        f'<path fill="{color}" d="{_SHIELD_PATH}"/>'
        f'</svg>'
    )


def make_shield_image(color: str = "#546ac1", pixel_size: int = 96) -> Gtk.Image:
    """
    Create a Gtk.Image displaying the BulwarkOS shield SVG.
    Writes to a temp file because Gtk.Image.new_from_file() is the most
    reliable cross-version way to load SVG in GTK4 without extra deps.
    """
    svg = make_shield_svg(color=color, size=pixel_size)
    tmp = tempfile.NamedTemporaryFile(suffix=".svg", delete=False)
    try:
        tmp.write(svg.encode())
        tmp.flush()
        img = Gtk.Image.new_from_file(tmp.name)
        img.set_pixel_size(pixel_size)
    finally:
        tmp.close()
        try:
            os.unlink(tmp.name)
        except OSError:
            pass
    return img


# ---------------------------------------------------------------------------
# Simple inline SVG icons for template cards
# Each returns a complete <svg> string sized to fit a 28px icon circle.
# ---------------------------------------------------------------------------

def _icon_svg(inner_paths: str, vb: str = "0 0 24 24") -> str:
    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="{vb}" '
        f'width="28" height="28" fill="white">{inner_paths}</svg>'
    )


